      "<!-- a couple of small shells resting flat on the sand; flat scatter -> no shadow -->\n<!-- SCALLOP / fan shell (left, lit warm) -->\n<path d=\"M -7,1 C -8.4,-3.6 -3.2,-6.2 -1.2,-2 C -1.6,-1 -1.8,-0.2 -1.6,0.8 Z\" fill=\"#d8ccab\" stroke=\"#5a4a2e\" stroke-width=\"0.9\" stroke-linejoin=\"round\"/>\n<!-- scallop shade (lower-right ribs side) -->\n<path d=\"M -3.6,0.6 C -2.6,-2.4 -1.8,-2.6 -1.2,-2 C -1.6,-1 -1.8,-0.2 -1.6,0.8 Z\" fill=\"#c8b890\" stroke=\"none\"/>\n<!-- fan ribs -->\n<path d=\"M -4.2,0.4 L -4.9,-3.4\" fill=\"none\" stroke=\"#5a4a2e\" stroke-width=\"0.4\" stroke-linecap=\"round\" opacity=\"0.55\"/>\n<path d=\"M -3,0.6 L -2.6,-3.2\" fill=\"none\" stroke=\"#5a4a2e\" stroke-width=\"0.4\" stroke-linecap=\"round\" opacity=\"0.5\"/>\n<path d=\"M -5.4,0.2 L -6.6,-2.6\" fill=\"none\" stroke=\"#5a4a2e\" stroke-width=\"0.4\" stroke-linecap=\"round\" opacity=\"0.5\"/>\n<!-- SPIRAL / conch shell (right, muted rose) -->\n<path d=\"M 3,2 C 1.4,-1.2 3.4,-4.2 6,-3.4 C 8.4,-2.6 8.2,0.6 6,1.6 C 5,2 4,2.2 3,2 Z\" fill=\"#c98a8a\" stroke=\"#5a4a2e\" stroke-width=\"0.9\" stroke-linejoin=\"round\" opacity=\"0.92\"/>\n<!-- spiral shade (lower-right) -->\n<path d=\"M 4,1.8 C 6.4,1.8 7.8,0.4 6.6,-1.6 C 7.8,-0.4 7.6,1.2 6,1.6 C 5.2,1.9 4.6,1.9 4,1.8 Z\" fill=\"#a86f6f\" stroke=\"none\" opacity=\"0.85\"/>\n<!-- spiral coil line -->\n<path d=\"M 5.4,0.4 C 4.4,-0.6 5.2,-1.8 6.2,-1.2 C 6.9,-0.8 6.6,0.2 5.8,0.2\" fill=\"none\" stroke=\"#5a4a2e\" stroke-width=\"0.45\" stroke-linecap=\"round\" opacity=\"0.6\"/>",
